local H=game:GetService('HttpService') local p=game.Players.LocalPlayer local g=p.PlayerGui.PunchWallHUD local a=g.PunchWallClientAutomation
a:Invoke('OpenTab','Pets') task.wait(.3) local states={}
for i=1,2 do a:Invoke('SelectInventoryItem','pet:slot:'..i) task.wait(.1) local s=a:Invoke('InventorySnapshot') assert(s.selected and s.selected.name=='Crystal Fox' and s.selected.slot==i,'wrong duplicate selected') assert(s.selected.locked==(i==2),'duplicate lock state leaked')
 local card for _,d in ipairs(g.GameMenu.FunctionalInventory:GetDescendants()) do if d:IsA('GuiObject') and d:GetAttribute('InventoryKey')=='pet:slot:'..i then card=d break end end assert(card and card.Visible and card:GetAttribute('InventoryLocked')==(i==2),'actual card lock disagrees with selected row') table.insert(states,{slot=i,locked=s.selected.locked}) end
return H:JSONEncode({ok=true,states=states})

local H=game:GetService('HttpService') local p=game.Players.LocalPlayer local g=p.PlayerGui.PunchWallHUD local a=g.PunchWallClientAutomation
local s=a:Invoke('Snapshot') assert(s.trainingVisible and g:GetAttribute('ContinuousTrainingAnimation')==true,'actual training state/overlay missing') local label=assert(g:FindFirstChild('TrainingStatus',true)) assert(label.Text:find('+4 POWER / SEC',1,true),'training payout label incorrect') local exit=assert(g:FindFirstChild('ExitTraining',true)) assert(exit.Visible and exit.Active,'training exit missing')
return H:JSONEncode({ok=true,trainingVisible=s.trainingVisible,label=label.Text})
